DROP TABLE IF EXISTS `quiz_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_log` (
  `quiz_log_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `quiz_id` bigint NOT NULL,
  `solved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`quiz_log_id`),
  KEY `fk_quiz_log_user` (`user_id`),
  KEY `fk_quiz_log_quiz` (`quiz_id`),
  CONSTRAINT `fk_quiz_log_quiz` FOREIGN KEY (`quiz_id`) REFERENCES `quiz_question` (`quiz_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_quiz_log_user` FOREIGN KEY (`user_id`) REFERENCES `member` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
