DROP TABLE IF EXISTS `quiz_question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_question` (
  `quiz_id` bigint NOT NULL,
  `mission_id` bigint DEFAULT NULL,
  `type` int DEFAULT NULL,
  `question` varchar(500) DEFAULT NULL,
  `answer` int DEFAULT NULL,
  `explanation` varchar(500) DEFAULT NULL,
  `point` int DEFAULT NULL,
  `quiz_date` datetime DEFAULT NULL,
  PRIMARY KEY (`quiz_id`),
  KEY `fk_quiz_mission` (`mission_id`),
  CONSTRAINT `fk_quiz_mission` FOREIGN KEY (`mission_id`) REFERENCES `mission` (`mission_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
