INSERT INTO `quiz_question` VALUES (1,1,1,'인플레이션(Inflation)이 발생하면 화폐의 가치는 떨어진다.',1,'물가가 오르면 같은 돈으로 살 수 있는 물건이 적어지므로 화폐 가치는 하락합니다.',100,'2026-01-30 00:00:00'),(2,1,1,'고위험 고수익(High Risk, High Return) 원칙에 따라, 기대 수익이 높으면 위험도 높은 경우가 많다.',1,'일반적으로 높은 수익을 기대할 수 있는 투자처는 원금 손실의 위험도 큽니다.',100,'2026-01-31 00:00:00'),(3,1,1,'주식 시장에서 매수(Buy)는 주식을 파는 것을 의미한다.',2,'매수는 사는 것, 매도(Sell)는 파는 것을 의미합니다.',100,'2026-02-01 00:00:00'),(4,1,1,'기준금리를 인상하면 일반적으로 대출 이자가 줄어든다.',2,'기준금리가 오르면 은행의 자금 조달 비용이 늘어나 대출 이자도 함께 오릅니다.',100,'2026-02-02 00:00:00'),(5,1,1,'대한민국 예금자보호법에 따라 보호받을 수 있는 한도는 1인당 원금과 이자를 합쳐 5천만 원이다.',1,'금융사가 파산해도 예금보험공사가 1인당 최대 5천만 원까지 보호해 줍니다.',100,'2026-02-03 00:00:00'),(6,1,1,'불황은 경기가 침체되어 경제 활동이 위축된 상태를 말한다.',1,'생산과 소비가 줄어들고 실업률이 높아지는 시기를 불황이라고 합니다.',100,'2026-02-04 00:00:00'),(7,1,1,'채권(Bond)을 산다는 것은 그 회사의 주인이 된다는 뜻이다.',2,'채권은 회사에 돈을 빌려주는(빚) 것이고, 주인이 되는 것은 주식입니다.',100,'2026-02-05 00:00:00'),(8,1,1,'환율이 오르면(원화 가치 하락), 수출하는 기업에게는 일반적으로 유리하다.',1,'1달러짜리 물건을 팔았을 때 받는 원화가 많아지므로 수출 기업의 이익이 늘어날 수 있습니다.',100,'2026-02-06 00:00:00'),(9,1,1,'신용등급이 높을수록 은행에서 돈을 빌릴 때 금리가 낮아진다.',1,'신용이 좋으면 돈을 떼일 확률이 낮다고 판단하여 더 낮은 이자로 빌려줍니다.',100,'2026-02-07 00:00:00'),(10,1,1,'적금은 목돈을 한 번에 맡겨두는 상품이고, 예금은 매달 돈을 붓는 상품이다.',2,'반대입니다. 적금은 매달 붓는 것, 예금(Deposit)은 목돈을 묶어두는 것입니다.',100,'2026-02-08 00:00:00'),(11,1,2,'다음 중 일반적으로 안전 자산으로 분류되기 가장 어려운 것은?',4,'암호화폐는 가격 변동성이 매우 커서 위험 자산으로 분류됩니다.',100,'2026-01-30 00:00:00'),(12,1,2,'대한민국의 통화정책을 수립하고 집행하는 중앙은행의 이름은?',2,'한국은행은 우리나라의 유일한 중앙은행으로 화폐를 발행합니다.',100,'2026-01-31 00:00:00'),(13,1,2,'국가의 경제 규모를 나타내는 지표인 GDP의 뜻은?',1,'GDP는 Gross Domestic Product의 약자로 국내총생산을 뜻합니다.',100,'2026-02-01 00:00:00'),(14,1,2,'주식 시장에서 주가가 상승하는 강세장을 동물의 뿔에 비유하여 무엇이라 하는가?',2,'황소(Bull)가 뿔로 들이받아 올리는 모습에서 유래하여 상승장을 불마켓이라 합니다.',100,'2026-02-02 00:00:00'),(15,1,2,'기업의 특정 시점의 재무 상태(자산, 부채, 자본)를 보여주는 표는?',2,'기업이 현재 무엇을 가졌고(자산) 얼마나 빚졌는지(부채) 보여주는 표입니다.',100,'2026-02-03 00:00:00'),(16,1,2,'빚투라는 신조어의 의미로 가장 적절한 것은?',1,'대출을 받거나 돈을 빌려서 무리하게 투자하는 것을 뜻하는 말입니다.',100,'2026-02-04 00:00:00'),(17,1,2,'연 금리가 1%일 때, 100만 원을 1년 동안 예금하면 받을 수 있는 이자(세전)는?',2,'100만 원의 1%는 1만 원입니다.',100,'2026-02-05 00:00:00'),(18,1,2,'다음 중 소비자가 물건을 살 때 가격에 포함되어 내는 세금(10%)은?',3,'부가가치세는 재화나 용역의 소비에 대해 부과되는 일반 소비세입니다.',100,'2026-02-06 00:00:00'),(19,1,2,'계란을 한 바구니에 담지 마라라는 격언이 설명하는 투자 원칙은?',3,'위험을 줄이기 위해 여러 자산에 나누어 투자하라는 분산 투자의 중요성을 말합니다.',100,'2026-02-07 00:00:00'),(20,1,2,'코스피(KOSPI) 지수는 어느 나라의 주식 시장을 대표하는 지수인가?',4,'KOSPI는 대한민국 유가증권시장의 종합주가지수입니다.',100,'2026-02-08 00:00:00'),(21,1,1,'기준금리가 인하되면 시중에 통화량(돈의 양)이 줄어든다.',2,'금리가 낮아지면 대출이 늘어나 시중에 돈이 더 많이 풀리게 됩니다.',100,'2026-02-09 00:00:00'),(22,1,1,'ETF(상장지수펀드)는 주식처럼 장중에 실시간으로 사고팔 수 있다.',1,'ETF는 펀드이지만 주식시장에 상장되어 있어 주식처럼 거래가 가능합니다.',100,'2026-02-10 00:00:00'),(23,1,1,'PER(주가수익비율)이 낮을수록 일반적으로 저평가된 주식으로 간주한다.',1,'PER가 낮다는 것은 이익 대비 주가가 낮다는 뜻이므로 저평가 매력이 있을 수 있습니다.',100,'2026-02-11 00:00:00'),(24,1,1,'손절매(Stop Loss)란 이익을 확정 짓기 위해 주식을 파는 행위이다.',2,'손절매는 더 큰 손실을 막기 위해 손해를 감수하고 파는 것을 말합니다. 이익 실현은 익절매입니다.',100,'2026-02-12 00:00:00'),(25,1,1,'단리(Simple Interest)는 원금에 대해서만 이자가 붙는 방식이다.',1,'원금에만 이자가 붙으면 단리, 이자에 이자가 붙으면 복리입니다.',100,'2026-02-13 00:00:00'),(26,1,1,'코스닥(KOSDAQ)은 주로 대기업 위주의 주식이 거래되는 시장이다.',2,'코스닥은 주로 벤처기업, 중소기업, 기술주 중심의 시장입니다. 대기업은 주로 코스피(KOSPI)입니다.',100,'2026-02-14 00:00:00'),(27,1,1,'선물(Futures) 거래는 미래의 특정 시점에 물건을 주고받기로 미리 약속하는 거래다.',1,'현재 시점에서 미래의 가격과 날짜를 정해 거래하는 파생상품입니다.',100,'2026-02-15 00:00:00'),(28,1,1,'LTV(주택담보대출비율)가 70%라면, 5억짜리 집을 담보로 최대 3억 5천만 원까지 빌릴 수 있다.',1,'주택 가격의 70%인 3.5억까지 대출이 가능하다는 의미입니다.',100,'2026-02-16 00:00:00'),(29,1,1,'환율이 1달러에 1200원에서 1300원으로 오르면 원화 가치는 상승한 것이다.',2,'환율 상승은 원화 가치 하락(원화 약세)을 의미합니다.',100,'2026-02-17 00:00:00'),(30,1,1,'유상증자는 기업이 주식을 새로 발행해 자본금을 늘리는 것을 말한다.',1,'주주들에게 돈을 받고 새 주식을 나눠주어 회사의 자본을 늘리는 행위입니다.',100,'2026-02-18 00:00:00'),(31,1,1,'블루칩(Blue Chip)이란 재무구조가 튼튼하고 수익성이 높은 우량주를 뜻한다.',1,'포커 게임의 가장 비싼 칩에서 유래된 말로, 우량 기업을 의미합니다.',100,'2026-02-19 00:00:00'),(32,1,1,'물가가 지속적으로 하락하는 현상을 인플레이션이라고 한다.',2,'물가 하락은 디플레이션(Deflation)입니다.',100,'2026-02-20 00:00:00'),(33,1,1,'공모주 청약은 이미 상장된 주식을 증권사에서 사는 것이다.',2,'공모주는 상장되기 전 기업이 투자자에게 주식을 공개적으로 파는(청약) 것입니다.',100,'2026-02-21 00:00:00'),(34,1,1,'배당금은 회사가 이익을 냈을 때 주주들에게 나눠주는 돈이다.',1,'기업 이익의 일부를 주주에게 환원하는 것을 배당이라고 합니다.',100,'2026-02-22 00:00:00'),(35,1,1,'ROA(총자산순이익률)는 기업이 자산을 얼마나 효율적으로 굴려 이익을 냈는지 보여주는 지표다.',1,'Return On Assets의 약자로, 총자산 대비 순이익 비율입니다.',100,'2026-02-23 00:00:00'),(36,1,1,'서킷브레이커는 주가가 급등하거나 급락할 때 시장을 진정시키기 위해 매매를 일시 중단하는 제도다.',1,'주식 시장의 과열을 막기 위한 안전장치입니다.',100,'2026-02-24 00:00:00'),(37,1,1,'체크카드는 신용을 담보로 결제하고 나중에 돈을 갚는 방식이다.',2,'체크카드는 통장 잔고 내에서 즉시 결제되는 방식입니다. 신용카드가 나중에 갚는 방식입니다.',100,'2026-02-25 00:00:00'),(38,1,1,'CMA 통장은 하루만 맡겨도 이자가 붙는 수시입출금 통장이다.',1,'증권사 등에서 가입 가능하며 매일 이자가 정산되는 것이 특징입니다.',100,'2026-02-26 00:00:00'),(39,1,1,'DTI(총부채상환비율)는 내 소득 대비 갚아야 할 대출 원리금의 비율을 말한다.',1,'소득을 기준으로 대출 한도를 정하는 지표 중 하나입니다.',100,'2026-02-27 00:00:00'),(40,1,1,'스태그플레이션(Stagflation)은 경기가 좋은데 물가가 떨어지는 현상이다.',2,'경기는 침체(Stagnation)되는데 물가는 오르는(Inflation) 최악의 경제 상황을 말합니다.',100,'2026-02-28 00:00:00'),(41,1,1,'액면분할을 하면 기업의 전체 자본금이 늘어난다.',2,'주식 수만 늘어나고 1주당 가격이 낮아질 뿐, 기업의 전체 가치나 자본금은 변하지 않습니다.',100,'2026-03-01 00:00:00'),(42,1,1,'RP(환매조건부채권)는 일정 기간 후 이자를 붙여 되사는 조건으로 발행하는 채권이다.',1,'금융기관이 일정 기간 후 다시 사주는 조건으로 판매하는 단기 금융 상품입니다.',100,'2026-03-02 00:00:00'),(43,1,1,'ISA(개인종합자산관리계좌)는 한 계좌로 예금, 펀드, 주식 등 다양한 상품을 관리하며 절세 혜택을 받는 계좌다.',1,'일명 만능통장으로 불리며 비과세 및 분리과세 혜택이 있습니다.',100,'2026-03-03 00:00:00'),(44,1,1,'비트코인은 중앙은행이 발행하고 관리하는 법정 화폐이다.',2,'비트코인은 탈중앙화된 암호화폐로, 중앙은행의 통제를 받지 않습니다.',100,'2026-03-04 00:00:00'),(45,1,1,'마이너스 통장은 쓴 만큼만 이자를 낸다.',1,'대출 한도 내에서 사용한 금액과 기간에 대해서만 이자가 부과됩니다.',100,'2026-03-05 00:00:00'),(46,1,1,'주식 배당락일에는 일반적으로 주가가 상승하는 경향이 있다.',2,'배당을 받을 권리가 사라진 날이므로, 이론적으로 배당금만큼 주가가 떨어져서 시작하는 경우가 많습니다.',100,'2026-03-06 00:00:00'),(47,1,1,'보통주와 달리 의결권은 없지만 배당을 더 많이 주는 주식을 우선주라고 한다.',1,'경영 참여(의결권)보다는 배당 수익을 선호하는 투자자에게 적합합니다.',100,'2026-03-07 00:00:00'),(48,1,1,'펀드매니저가 투자자를 대신해 운용해 주는 펀드를 액티브 펀드라고 한다.',1,'시장 수익률 초과를 목표로 적극적으로 운용하는 펀드입니다.',100,'2026-03-08 00:00:00'),(49,1,1,'신용점수는 대출을 전혀 받지 않고 신용카드도 안 쓰면 가장 높게 유지된다.',2,'적절한 신용거래(카드 사용, 대출 상환) 이력이 있어야 신용점수가 오릅니다. 정보가 없으면 중간 등급을 받습니다.',100,'2026-03-09 00:00:00'),(50,1,1,'리츠(REITs)는 다수의 투자자로부터 자금을 모아 부동산에 투자하고 수익을 배당하는 회사다.',1,'소액으로도 부동산 투자가 가능하게 해주는 주식 형태의 상품입니다.',100,'2026-03-10 00:00:00'),(51,1,1,'옵션(Option)에서 콜(Call) 옵션은 살 수 있는 권리, 풋(Put) 옵션은 팔 수 있는 권리다.',1,'콜=살 권리, 풋=팔 권리입니다.',100,'2026-03-11 00:00:00'),(52,1,1,'기축통화란 국제 거래에서 중심이 되는 통화로 현재는 유로화가 대표적이다.',2,'현재 전 세계의 기축통화는 미국 달러(USD)입니다.',100,'2026-03-12 00:00:00'),(53,1,1,'유동성이란 자산을 현금으로 얼마나 빨리 바꿀 수 있는가를 의미한다.',1,'현금은 유동성이 가장 높고, 부동산은 유동성이 낮은 자산입니다.',100,'2026-03-13 00:00:00'),(54,1,1,'BIS 자기자본비율은 은행의 건전성을 나타내는 지표다.',1,'국제결제은행(BIS)이 권고하는 은행의 위험자산 대비 자기자본 비율입니다.',100,'2026-03-14 00:00:00'),(55,1,1,'턴어라운드(Turnaround)란 적자 기업이 실적 개선을 통해 흑자로 전환하는 것을 말한다.',1,'기업 회생이나 실적 호전을 의미하는 용어입니다.',100,'2026-03-15 00:00:00'),(56,1,1,'B2B는 기업과 소비자 간의 거래를 의미한다.',2,'B2B는 기업 대 기업(Business to Business), 기업 대 소비자는 B2C입니다.',100,'2026-03-16 00:00:00'),(57,1,1,'M&A는 기업의 인수와 합병을 의미한다.',1,'Mergers and Acquisitions의 약자입니다.',100,'2026-03-17 00:00:00'),(58,1,1,'연말정산 시 신용카드 공제율이 체크카드보다 높다.',2,'일반적으로 체크카드와 현금영수증의 소득공제율(30%)이 신용카드(15%)보다 높습니다.',100,'2026-03-18 00:00:00'),(59,1,1,'금리 역전 현상이란 장기 금리가 단기 금리보다 낮아지는 현상을 말한다.',1,'보통 장기 금리가 높아야 정상인데, 이것이 뒤집히면 경기 침체의 전조로 해석되곤 합니다.',100,'2026-03-19 00:00:00'),(60,1,1,'사모펀드는 불특정 다수(50인 이상)에게 공개적으로 자금을 모으는 펀드다.',2,'사모펀드는 49인 이하의 소수 투자자로부터 비공개로 자금을 모으는 펀드입니다. (공모펀드 반대)',100,'2026-03-20 00:00:00'),(61,1,1,'치킨게임(Chicken Game)은 어느 한쪽이 양보할 때까지 출혈 경쟁을 하는 상황을 말한다.',1,'기업들이 경쟁사를 이기기 위해 손해를 보면서까지 가격을 낮추는 경쟁 등을 말합니다.',100,'2026-03-21 00:00:00'),(62,1,1,'엥겔지수가 높을수록 생활 형편이 넉넉한 가구로 볼 수 있다.',2,'엥겔지수는 가계 지출 중 식료품비 비율로, 높을수록 저소득층일 확률이 높습니다.',100,'2026-03-22 00:00:00'),(63,1,1,'빅맥지수는 각국의 물가 수준을 햄버거 가격으로 비교하는 지수다.',1,'맥도날드 빅맥 가격을 기준으로 환율과 구매력을 평가하는 지수입니다.',100,'2026-03-23 00:00:00'),(64,1,1,'뱅크런(Bank Run)은 은행이 예금 지급 불능 상태에 빠질 것을 우려해 고객들이 대규모로 예금을 인출하는 사태다.',1,'은행의 신용도가 떨어졌을 때 발생하는 대량 인출 사태입니다.',100,'2026-03-24 00:00:00'),(65,1,1,'GDP 디플레이터는 명목 GDP를 실질 GDP로 나눈 값으로 국가 전반의 물가 수준을 나타낸다.',1,'가장 포괄적인 물가 지수 중 하나입니다.',100,'2026-03-25 00:00:00'),(66,1,1,'OEM은 주문자가 만든 제품에 상표만 부착하는 생산 방식이다.',2,'OEM은 주문자가 설계하고 생산만 맡기는 것이고, ODM은 생산자가 개발과 생산을 모두 하는 것입니다.',100,'2026-03-26 00:00:00'),(67,1,1,'FAANG은 미국의 대표적인 IT 기업인 페이스북, 아마존, 애플, 넷플릭스, 구글을 묶어 부르는 말이다.',1,'미국 기술주를 대표하는 용어였습니다 (최근엔 MATANA 등으로 변하기도 함).',100,'2026-03-27 00:00:00'),(68,1,1,'유니콘 기업은 기업 가치가 1조 원(10억 달러) 이상인 상장 기업을 말한다.',2,'상장되지 않은(비상장) 스타트업 중 가치가 1조 원 이상인 기업을 말합니다.',100,'2026-03-28 00:00:00'),(69,1,1,'오픈뱅킹은 하나의 앱으로 자신의 모든 은행 계좌를 조회하고 이체할 수 있는 서비스다.',1,'은행 간 장벽을 허물어 핀테크 편의성을 높인 서비스입니다.',100,'2026-03-29 00:00:00'),(70,1,1,'ESG 경영은 환경, 사회, 지배구조를 고려하는 지속 가능한 경영 방식을 말한다.',1,'Environment, Social, Governance의 약자입니다.',100,'2026-03-30 00:00:00'),(71,1,2,'주식 투자의 대가 워런 버핏이 운영하는 회사의 이름은?',1,'버크셔 해서웨이는 워런 버핏이 이끄는 지주회사입니다.',100,'2026-02-09 00:00:00'),(72,1,2,'다음 중 제1금융권에 해당하지 않는 금융기관은?',3,'저축은행은 제2금융권에 해당합니다.',100,'2026-02-10 00:00:00'),(73,1,2,'기업이 주식 시장에 처음으로 상장하기 위해 기업을 공개하는 것을 무엇이라 하는가?',1,'IPO(Initial Public Offering)는 기업공개를 뜻합니다.',100,'2026-02-11 00:00:00'),(74,1,2,'주식 차트에서 붉은색 막대(양봉)가 의미하는 것은?',1,'시가(시작 가격)보다 종가(마감 가격)가 높게 끝났음을 의미합니다.',100,'2026-02-12 00:00:00'),(75,1,2,'다음 중 세금의 종류가 다른 하나는?',4,'부가세, 개별소비세, 주세는 간접세이고, 소득세는 직접세입니다.',100,'2026-02-13 00:00:00'),(76,1,2,'PBR(주가순자산비율)이 1배 미만이라는 것은 무엇을 의미하는가?',2,'회사를 당장 청산한 가치보다 주가 총액이 더 낮게 평가받고 있다는 뜻입니다.',100,'2026-02-14 00:00:00'),(77,1,2,'세계 3대 신용평가기관이 아닌 것은?',4,'모건스탠리는 투자은행(IB)입니다. S&P, 무디스, 피치가 3대 평가사입니다.',100,'2026-02-15 00:00:00'),(78,1,2,'다음 중 파생상품에 해당하지 않는 것은?',1,'보통주는 기초자산(주식) 그 자체이며 파생상품이 아닙니다.',100,'2026-02-16 00:00:00'),(79,1,2,'경제 고통 지수(Misery Index)를 구성하는 두 가지 요소는?',2,'경제 고통 지수는 실업률과 물가상승률을 합친 수치입니다.',100,'2026-02-17 00:00:00'),(80,1,2,'다음 중 금리 인상 시기에 일반적으로 유리한 업종은?',1,'은행은 예대마진(대출금리-예금금리 차이)이 확대되어 수익이 늘어나는 경향이 있습니다.',100,'2026-02-18 00:00:00'),(81,1,2,'최초의 암호화폐인 비트코인을 개발한 것으로 알려진 인물의 가명은?',3,'나카모토 사토시라는 익명의 개발자가 비트코인 백서를 발표했습니다.',100,'2026-02-19 00:00:00'),(82,1,2,'주가 조작이나 내부자 거래 등 불공정 거래를 감시하는 우리나라 기관은?',2,'금융감독원은 금융기관의 감독과 검사 업무를 수행합니다.',100,'2026-02-20 00:00:00'),(83,1,2,'달러 인덱스가 100을 넘었다는 것은 무엇을 의미하는가?',1,'주요 6개국 통화 대비 달러의 가치가 기준 시점보다 강세라는 뜻입니다.',100,'2026-02-21 00:00:00'),(84,1,2,'다음 중 워크아웃(Workout)의 의미로 가장 적절한 것은?',2,'부도 위기의 기업이 채권단과 협의하여 재무 구조를 개선하고 회생을 도모하는 과정입니다.',100,'2026-02-22 00:00:00'),(85,1,2,'주식 시장에서 동시호가 제도가 적용되는 시간대는?',1,'장 시작 전(8:30~9:00)과 장 마감 전(15:20~15:30)에 접수된 주문을 모아 하나의 가격으로 체결시킵니다.',100,'2026-02-23 00:00:00'),(86,1,2,'선물옵션 만기일이 겹쳐 주식 시장 변동성이 커지는 날을 무엇이라 하는가?',3,'네 마녀가 심술을 부린다는 뜻에서 쿼드러플 위칭데이라고 합니다.',100,'2026-02-24 00:00:00'),(87,1,2,'다음 중 보유세에 해당하는 세금은?',1,'재산세와 종합부동산세는 부동산을 보유하고 있을 때 내는 세금입니다.',100,'2026-02-25 00:00:00'),(88,1,2,'경제학에서 말하는 보이지 않는 손을 주장한 학자는?',2,'애덤 스미스는 국부론에서 시장의 가격 조정 기능을 보이지 않는 손에 비유했습니다.',100,'2026-02-26 00:00:00'),(89,1,2,'매달 월급처럼 따박따박 배당을 주는 ETF를 무엇이라 하는가?',4,'매월 분배금을 지급하는 ETF를 월배당 ETF라고 합니다.',100,'2026-02-27 00:00:00'),(90,1,2,'다음 중 안전자산 선호 심리가 강해질 때 가격이 오르는 것은?',1,'전쟁이나 위기 시에는 금, 달러 같은 안전자산의 수요가 늘어납니다.',100,'2026-02-28 00:00:00'),(91,1,2,'개인이 주식 투자를 통해 얻을 수 있는 소득이 아닌 것은?',3,'퇴직 소득은 퇴직 시 받는 급여입니다. 주식으로는 배당소득과 양도소득(매매차익)을 얻습니다.',100,'2026-03-01 00:00:00'),(92,1,2,'다음 중 유동비율을 구하는 공식은?',1,'유동자산을 유동부채로 나눈 비율로, 기업의 단기 채무 상환 능력을 보여줍니다.',100,'2026-03-02 00:00:00'),(93,1,2,'주식 매수 주문을 낼 때, 가격을 지정하지 않고 현재 가장 유리한 가격으로 즉시 체결시키는 주문은?',2,'시장가 주문은 가격 상관없이 물량을 바로 확보하고 싶을 때 사용합니다.',100,'2026-03-03 00:00:00'),(94,1,2,'다음 중 미국 뉴욕증권거래소(NYSE)를 상징하는 동물은?',1,'월스트리트의 황소 동상이 유명합니다.',100,'2026-03-04 00:00:00'),(95,1,2,'기업이 1년 동안 벌어들인 순이익을 발행 주식 수로 나눈 값은?',1,'EPS(Earning Per Share)는 주당순이익을 말합니다.',100,'2026-03-05 00:00:00'),(96,1,2,'다음 중 핀테크(FinTech)와 관련이 가장 먼 것은?',4,'오프라인 지점 창구는 전통적인 금융 방식입니다.',100,'2026-03-06 00:00:00'),(97,1,2,'국가가 빚을 갚지 못하겠다고 선언하는 것을 무엇이라 하는가?',1,'모라토리엄(지불 유예)보다 더 심각한 상태인 디폴트(채무 불이행) 선언입니다.',100,'2026-03-07 00:00:00'),(98,1,2,'다음 중 소득 분배의 불평등 정도를 나타내는 지수는?',2,'지니계수는 0에 가까울수록 평등하고 1에 가까울수록 불평등함을 나타냅니다.',100,'2026-03-08 00:00:00'),(99,1,2,'주식 차트에서 골든크로스가 발생했다는 것은 무엇을 의미하는가?',1,'단기 이동평균선이 장기 이동평균선을 뚫고 올라가는 현상으로, 매수 신호로 해석됩니다.',100,'2026-03-09 00:00:00'),(100,1,2,'테이퍼링(Tapering)의 경제적 의미는?',1,'양적완화(돈 풀기)의 규모를 점차 줄여나가는 출구 전략을 의미합니다.',100,'2026-03-10 00:00:00'),(101,1,2,'우리나라의 회계연도 기준일은 언제인가?',4,'대부분의 기업과 정부 회계는 1월 1일부터 12월 31일까지를 회계연도로 잡습니다.',100,'2026-03-11 00:00:00'),(102,1,2,'다음 중 기업의 부채 비율을 계산할 때 포함되지 않는 것은?',3,'자본잉여금은 자본 항목이지 부채가 아닙니다.',100,'2026-03-12 00:00:00'),(103,1,2,'코스피 시장의 가격 제한폭(상한가/하한가)은 몇 퍼센트인가?',3,'현재 한국 주식시장의 가격 제한폭은 ±30%입니다.',100,'2026-03-13 00:00:00'),(104,1,2,'달러가 아닌 다른 나라의 통화를 서로 직접 교환하는 시장은?',2,'이종통화시장은 달러를 거치지 않고 엔화-원화 등을 직접 거래하는 시장을 말할 때 쓰입니다.',100,'2026-03-14 00:00:00'),(105,1,2,'기업이 자사주를 매입하여 소각하면 나타나는 효과는?',1,'주식 수가 줄어들어 1주당 가치(EPS)가 상승하는 주가 부양 효과가 있습니다.',100,'2026-03-15 00:00:00'),(106,1,2,'다음 중 직접금융 시장에 해당하는 것은?',1,'주식시장은 기업이 투자자로부터 직접 자금을 조달하는 시장입니다. 은행은 간접금융입니다.',100,'2026-03-16 00:00:00'),(107,1,2,'메타버스(Metaverse)와 가장 관련이 깊은 기술은?',2,'VR(가상현실)과 AR(증강현실)은 메타버스의 핵심 기술입니다.',100,'2026-03-17 00:00:00'),(108,1,2,'다음 중 환헤지(Hedge) 상품에 가입하는 주된 이유는?',2,'환율 변동에 따른 위험(손실)을 피하기 위해 가입합니다.',100,'2026-03-18 00:00:00'),(109,1,2,'주식 시장에서 VI(변동성 완화장치)가 발동되는 이유는?',1,'주가가 갑자기 급변할 때 잠시 냉각기를 주어 투자자를 보호하기 위함입니다.',100,'2026-03-19 00:00:00'),(110,1,2,'다음 중 NFT(대체 불가능 토큰)의 특징으로 옳은 것은?',2,'블록체인 기술을 이용해 디지털 자산의 소유권을 증명하는 토큰으로 고유성을 가집니다.',100,'2026-03-20 00:00:00'),(111,1,2,'경제 활동 가능 인구 중 일할 의사는 있지만 일자리를 구하지 못한 사람의 비율은?',1,'실업률에 대한 정의입니다.',100,'2026-03-21 00:00:00'),(112,1,2,'다음 중 기회비용에 대한 설명으로 옳은 것은?',3,'어떤 선택을 함으로써 포기해야 하는 다른 선택지 중 가장 가치가 큰 것을 말합니다.',100,'2026-03-22 00:00:00'),(113,1,2,'기업의 영업이익에서 이자 비용을 얼마나 감당할 수 있는지 보여주는 지표는?',2,'이자보상배율이 1 미만이면 벌어서 이자도 못 낸다는 뜻입니다.',100,'2026-03-23 00:00:00'),(114,1,2,'선물 거래에서 증거금이 부족할 때 추가 입금을 요구하는 것은?',1,'마진콜(Margin Call)이 발생하면 돈을 더 넣거나 강제 청산당하게 됩니다.',100,'2026-03-24 00:00:00'),(115,1,2,'다음 중 단기 금융 상품인 CD의 우리말 명칭은?',1,'양도성 예금증서(Certificate of Deposit)의 약자입니다.',100,'2026-03-25 00:00:00'),(116,1,2,'우리나라 주식시장의 정규 거래 시간은?',2,'오전 9시부터 오후 3시 30분까지입니다.',100,'2026-03-26 00:00:00'),(117,1,2,'다음 중 레버리지(Leverage) 효과를 설명하는 도구는?',1,'지렛대(Lever)를 이용하여 적은 힘으로 무거운 물건을 들듯, 빚을 이용해 수익률을 극대화하는 것입니다.',100,'2026-03-27 00:00:00'),(118,1,2,'달걀 모형 이론에서 금리가 고점일 때 추천되는 투자처는?',4,'금리가 높을 때는 안전하고 이자를 많이 주는 예금으로 자금이 이동합니다.',100,'2026-03-28 00:00:00'),(119,1,2,'주식 배당금을 받기 위해 주식을 보유하고 있어야 하는 마지막 날은?',2,'배당기준일의 2영업일 전까지 매수해야 주주 명부에 등재됩니다.',100,'2026-03-29 00:00:00'),(120,1,2,'다음 중 행동경제학 용어인 넛지(Nudge)의 뜻은?',3,'타인의 선택을 유도하는 부드러운 개입을 뜻합니다 (팔꿈치로 슬쩍 찌르다).',100,'2026-03-30 00:00:00');
